    private ScannerLexicoCpp scanner;
    public  SymbolTable         tablaSimbolos = new SymbolTable();
    public  List<SemanticError> erroresSem    = new ArrayList<>();
    public  TACGenerator        tac           = new TACGenerator();
    public  java.util.Deque<String[]> labelStack   = new java.util.ArrayDeque<>();
    public  java.util.Deque<String[]> switchStack  = new java.util.ArrayDeque<>();
